-- ============================================================================
-- DO NOT EDIT THIS FILE ONCE IT HAS BEEN APPLIED TO ANY DATABASE.
-- Until then it may still change. After it is applied, every change goes in a
-- new migration file with a later timestamp.
-- ============================================================================
--
-- Website leads: the quote form and chat widget on frenchsolarindustry.com
-- post to /api/webhooks/website-lead, which files each request as a lead.
--
-- Add-only, with two relaxations on customer_documents (section 3):
--   1. leads gets two new nullable columns: source and quote_details.
--   2. A new table, website_submissions, makes the webhook idempotent.
--   3. customer_documents.uploaded_by becomes nullable (null = uploaded by the
--      website, not a person) and document_type also accepts 'Meter Photo'.
--      A new check keeps null uploaded_by to meter photos only. The insert
--      policy still requires uploaded_by = auth.uid(), so signed-in users
--      cannot create rows without an uploader.
--   4. The customer-documents bucket also accepts the image types the quote
--      form allows (JPEG, PNG, WebP, HEIC, HEIF). The size limit is unchanged.
--   5. public.ingest_website_lead: matches or creates the lead in one
--      transaction. Security definer, callable by the server key only.
-- No existing row is rewritten.
--
-- Depends on 20261112090000_whatsapp.sql (leads.phone_wa, normalize_phone_wa).
-- NOT applied to production by the developer. The project owner reviews and
-- applies it (see docs/website-leads.md). Until it is applied the webhook
-- answers 503 and the website keeps its CSV and email copy.

-- 1. leads ---------------------------------------------------------------------

alter table public.leads
    add column source text,
    add column quote_details jsonb;

comment on column public.leads.source is
    'Where the lead first came from, e.g. website_quote, website_chat. Null for leads entered by staff.';
comment on column public.leads.quote_details is
    'Latest quote request from the website form (site type, installation, monthly cost, meter, location). Read-only in the CRM.';

-- 2. website_submissions ---------------------------------------------------------
-- One row per website submission id. A retry with the same id finds the row
-- and gets the same lead back instead of a second note or lead.

create table public.website_submissions (
    submission_id text primary key,
    lead_id bigint references public.leads (id) on delete cascade,
    form text not null,
    photo_path text,
    received_at timestamptz not null default now(),
    constraint website_submissions_form_check check (form = any (array['quote', 'chat'])),
    constraint website_submissions_id_check check (submission_id ~ '^[A-Za-z0-9_-]{16,64}$')
);

create index idx_website_submissions_lead_id on public.website_submissions (lead_id);

comment on table public.website_submissions is
    'Idempotency log for the website lead webhook. Written by the server only.';

-- RLS on with no policies: only the server key (which bypasses RLS) reads or
-- writes it. Signed-in staff have no reason to see it.
alter table public.website_submissions enable row level security;

-- 3. customer_documents ----------------------------------------------------------

alter table public.customer_documents
    alter column uploaded_by drop not null;

alter table public.customer_documents
    drop constraint customer_documents_type_check;

alter table public.customer_documents
    add constraint customer_documents_type_check
        check (document_type = any (array['Quotation', 'Proposal', 'Company Profile', 'Other', 'Meter Photo']));

alter table public.customer_documents
    add constraint customer_documents_uploader_check
        check (uploaded_by is not null or document_type = 'Meter Photo');

-- 4. storage ---------------------------------------------------------------------

update storage.buckets
set allowed_mime_types = array[
    'application/pdf', 'image/jpeg', 'image/png', 'image/webp', 'image/heic', 'image/heif'
]
where id = 'customer-documents';

-- 5. ingest_website_lead ---------------------------------------------------------
-- Matches the request to a lead by phone (same normalization as phone_wa) or
-- by email, case-insensitively. Several matches: the most recently updated one
-- gets the request, and the note names the others for a person to merge.
-- On a match: the note is appended, quote_details replaced by the newer quote
-- (a chat message keeps the old one), and empty phone or email filled in.
-- Status, owner and name are never changed. With no match a new lead is made:
-- status 'New', lead_type 'Customer', unassigned.
--
-- p_note is built by the webhook and must not mention other leads; this
-- function adds that line itself.
--
-- Security definer, like wa_find_or_create_lead: normalize_phone_wa (and the
-- leads phone_wa trigger) call into the private schema, which service_role
-- cannot use. Execute is revoked from everyone but service_role below, and
-- search_path is empty so every name is schema-qualified.

create or replace function public.ingest_website_lead(
    p_submission_id text,
    p_form text,
    p_source text,
    p_name text,
    p_phone text,
    p_email text,
    p_location text,
    p_note text,
    p_quote_details jsonb
)
returns table (lead_id bigint, created boolean, replayed boolean, photo_path text, other_matches bigint[])
language plpgsql
security definer
set search_path to ''
as $$
#variable_conflict use_column
declare
    v_phone_wa text := public.normalize_phone_wa(p_phone);
    v_email text := nullif(lower(trim(p_email)), '');
    v_existing public.website_submissions%rowtype;
    v_lead_id bigint;
    v_others bigint[];
    v_note text := p_note;
begin
    -- The primary key serializes two deliveries of the same submission.
    insert into public.website_submissions (submission_id, form)
    values (p_submission_id, p_form)
    on conflict (submission_id) do nothing;

    if not found then
        select * into v_existing from public.website_submissions s where s.submission_id = p_submission_id;
        return query select v_existing.lead_id, false, true, v_existing.photo_path, array[]::bigint[];
        return;
    end if;

    -- Two different submissions from the same person must not both create a lead.
    perform pg_advisory_xact_lock(hashtextextended('website_lead:' || coalesce(v_phone_wa, v_email, p_submission_id), 0));

    select array_agg(l.id order by l.updated_at desc nulls last, l.id desc)
    into v_others
    from public.leads l
    where (v_phone_wa is not null and l.phone_wa = v_phone_wa)
       or (v_email is not null and lower(trim(l.email)) = v_email);

    if v_others is not null and cardinality(v_others) > 0 then
        v_lead_id := v_others[1];
        v_others := v_others[2:];
        if cardinality(v_others) > 0 then
            v_note := v_note || E'\nAlso matches lead(s) ' || array_to_string(v_others, ', ') || '. Check for duplicates.';
        end if;

        update public.leads l
        set notes = case when coalesce(l.notes, '') = '' then v_note else l.notes || E'\n\n' || v_note end,
            quote_details = coalesce(p_quote_details, l.quote_details),
            phone = coalesce(nullif(trim(l.phone), ''), p_phone),
            email = coalesce(nullif(trim(l.email), ''), v_email)
        where l.id = v_lead_id;

        update public.website_submissions s set lead_id = v_lead_id where s.submission_id = p_submission_id;
        return query select v_lead_id, false, false, null::text, coalesce(v_others, array[]::bigint[]);
        return;
    end if;

    insert into public.leads (customer_name, phone, email, location, status, lead_type, status_started_at, notes, source, quote_details)
    values (p_name, p_phone, v_email, p_location, 'New', 'Customer', now(), v_note, p_source, p_quote_details)
    returning id into v_lead_id;

    update public.website_submissions s set lead_id = v_lead_id where s.submission_id = p_submission_id;
    return query select v_lead_id, true, false, null::text, array[]::bigint[];
end;
$$;

comment on function public.ingest_website_lead is
    'Files a website form submission as a lead (match by phone or email, else create). Server key only.';

revoke execute on function public.ingest_website_lead(text, text, text, text, text, text, text, text, jsonb) from public, anon, authenticated;
grant execute on function public.ingest_website_lead(text, text, text, text, text, text, text, text, jsonb) to service_role;
